INSERT INTO news (slug,title,excerpt,body,category,author,cover_url,video_url,status,published_at,source_url,original_date,archive_note,updated_at)
VALUES ('acikogretim-lisesi-ikinci-bir-sans-mi-yeni-zorluklar-mi','Açıköğretim Lisesi: İkinci Bir Şans mı, Yeni Zorluklar mı?','Örgün eğitimden açık liseye geçiş bazı öğrenciler için yeni bir başlangıç sunarken, süreç beraberinde maddi ve bürokratik sorunlar da getirebiliyor. 13 Eylül 2024 tarihli haberde Balıkesir’de yaşayan 16 yaşındaki Betül Tuncay’ın açıköğretim lisesine geçiş deneyimi üzerinden sistemin sahadaki etkileri ele alındı.','Örgün eğitimden açık liseye geçiş bazı öğrenciler için yeni bir başlangıç sunarken, süreç beraberinde maddi ve bürokratik sorunlar da getirebiliyor. 13 Eylül 2024 tarihli haberde Balıkesir’de yaşayan 16 yaşındaki Betül Tuncay’ın açıköğretim lisesine geçiş deneyimi üzerinden sistemin sahadaki etkileri ele alındı.

Tuncay, Hüma Hatun Kız Meslek Lisesi’nde iki dönem boyunca üç dersten kalmasının ardından örgün eğitim hakkını kaybettiğini, bu nedenle açık liseye yönelmek zorunda kaldığını anlattı. Mesleki açık lisede istediği bölüme geçememesi de seçeneklerini daraltan başlıklardan biri oldu.

Başvuru, kayıt, bölüm seçimi ve eğitim materyalleri gibi işlemler öğrenciler ve aileler için yalnızca idari değil ekonomik bir yük de oluşturabiliyor. Haberde, sistemin ''ikinci şans'' yaratmasının yanında öğrencinin bilgiye erişimi ve doğru yönlendirilmesi ihtiyacına da dikkat çekildi.

Bu arşiv haberi, eğitim politikalarının öğrencinin günlük hayatında nasıl karşılık bulduğunu bir genç öğrencinin deneyimi üzerinden görünür kılıyor.','Eğitim','Buse Tuncay','/assets/haber-kapak/acikogretim-lisesi-ikinci-bir-sans-mi-yeni-zorluklar-mi.webp','','published','2024-09-13T09:00:00+03:00','https://gazetemerhaba.com/acikogretim-lisesi-ikinci-bir-sans-mi-yeni','13 Eylül 2024','BTmedya için yeniden yazılmış arşiv sürümü. Orijinal yayın bilgileri korunmuştur.','2024-09-13T09:00:00+03:00')
