INSERT INTO news (slug,title,excerpt,body,category,author,cover_url,video_url,status,published_at,source_url,original_date,archive_note,updated_at)
VALUES ('balikesir-in-gururu-memleketinde-sov-yapacak','Balıkesir''in Gururu Memleketinde Şov Yapacak!','Balıkesirli binici Şevket Sarıdemir, 6 Eylül 2024’te Halalca Mahallesi’nde düzenlenecek at binme etkinliği öncesinde memleketinde sahne almaya hazırlanıyordu. 26 Ağustos 2024 tarihli haber, Sarıdemir’in spor geçmişi ile Halalca’daki etkinliği bir araya getiriyordu.','Balıkesirli binici Şevket Sarıdemir, 6 Eylül 2024’te Halalca Mahallesi’nde düzenlenecek at binme etkinliği öncesinde memleketinde sahne almaya hazırlanıyordu. 26 Ağustos 2024 tarihli haber, Sarıdemir’in spor geçmişi ile Halalca’daki etkinliği bir araya getiriyordu.

Sarıdemir’in yurt içi ve yurt dışındaki yarışmalarda dereceler elde ettiği, özellikle Avrupa’daki organizasyonlarda Balıkesir’i temsil ettiği aktarılmıştı. Haberde ayrıca Fransa’da kazandığı birinciliğin kariyerindeki dikkat çekici sonuçlardan biri olduğu belirtiliyordu.

Halalca’daki organizasyon yalnız bir spor karşılaşması olarak değil, bölgedeki atçılık kültürünün tanıtılması açısından da önem taşıyordu. Etkinliğe çevre illerden katılım beklenirken, Sarıdemir kendi memleketinde yarışmanın kendisi için ayrı bir anlam taşıdığını ifade etmişti.

Arşiv haberi, yerel bir sporcunun uluslararası deneyimini doğduğu şehirdeki geleneksel bir etkinlikle buluşturan hikâyeyi kayıt altına alıyor.','Spor','Buse Tuncay','/assets/haber-kapak/balikesir-in-gururu-memleketinde-sov-yapacak.webp','','published','2024-08-26T09:00:00+03:00','https://gazetemerhaba.com/balikesirin-gururu-memleketinde-sov-yapacak','26 Ağustos 2024','BTmedya için yeniden yazılmış arşiv sürümü. Orijinal yayın bilgileri korunmuştur.','2024-08-26T09:00:00+03:00')
