INSERT INTO news (slug,title,excerpt,body,category,author,cover_url,video_url,status,published_at,source_url,original_date,archive_note,updated_at)
VALUES ('el-emegi-yorganlar-artik-isitmiyor','El Emeği Yorganlar Artık Isıtmıyor!','Balıkesir’in tarihi Mobilyacılar Çarşısı’nda el yapımı yorgancılık, 2024’te giderek azalan taleple mücadele eden geleneksel mesleklerden biriydi. 19 Ağustos 2024 tarihli görüntülü haberde, 12 yaşından beri yorgancılık yapan Mehmet Deniz’in dükkânı ve mesleğin geleceği anlatıldı.','Balıkesir’in tarihi Mobilyacılar Çarşısı’nda el yapımı yorgancılık, 2024’te giderek azalan taleple mücadele eden geleneksel mesleklerden biriydi. 19 Ağustos 2024 tarihli görüntülü haberde, 12 yaşından beri yorgancılık yapan Mehmet Deniz’in dükkânı ve mesleğin geleceği anlatıldı.

Deniz’in aktardığına göre bir yorganın tamamen elle dikilmesi yaklaşık iki gün sürüyordu. El emeğinin yoğun olması ve malzeme maliyetleri nedeniyle yorgan fiyatları o dönemde yaklaşık 1500 TL ile 3500 TL arasında değişiyordu.

Fabrikasyon ürünlerin yaygınlaşması, tüketicinin alışkanlıklarının değişmesi ve el işçiliğinin fiyatının yükselmesi, yorgancılığı giderek daha dar bir müşteri kitlesine sıkıştırıyordu. Buna rağmen ustalar, yıllardır öğrendikleri teknikleri sürdürerek geleneksel üretimi yaşatmaya çalışıyordu.

Haber, kaybolmaya yüz tutan bir zanaatı yalnız ekonomik açıdan değil kültürel hafıza açısından da görünür kılıyor. Sayfadaki video bağlantısı arşivde ayrıca korunmuştur.','Kültür / Zanaat','Buse Tuncay','/assets/haber-kapak/el-emegi-yorganlar-artik-isitmiyor.webp','https://www.youtube.com/watch?v=Gex7VqNEH7w','published','2024-08-19T09:00:00+03:00','https://gazetemerhaba.com/el-emegi-yorganlar-artik-isitmiyor','19 Ağustos 2024','BTmedya için yeniden yazılmış arşiv sürümü. Orijinal yayın bilgileri korunmuştur.','2024-08-19T09:00:00+03:00')
