INSERT INTO news (slug,title,excerpt,body,category,author,cover_url,video_url,status,published_at,source_url,original_date,archive_note,updated_at)
VALUES ('balikesir-in-son-kalaycisi-ilyas-baykal','Balıkesir’in Son Kalaycısı: İlyas Baykal','Balıkesir Bakırcılar Çarşısı’nda yarım asrı aşan süredir çalışan İlyas Baykal, kentte kalaycılığı sürdüren son ustalardan biri olarak 7 Ağustos 2024 tarihli habere konu oldu.','Balıkesir Bakırcılar Çarşısı’nda yarım asrı aşan süredir çalışan İlyas Baykal, kentte kalaycılığı sürdüren son ustalardan biri olarak 7 Ağustos 2024 tarihli habere konu oldu.

Baykal, 12 yaşında başladığı mesleği 1967’den beri sürdürdüğünü anlattı. Balıkesir’in Gökköy köyünden merkeze geldiğinde farklı işlere yönelmeyi düşünürken, kalaycı olan ağabeylerinin etkisiyle bu zanaata adım attı.

Alüminyum ve çelik mutfak eşyalarının yaygınlaşması bakır kap kullanımını azaltınca kalaycılığa olan ihtiyaç da geriledi. Baykal’a göre usta olabilmek için yıllarca çıraklık yapmak gerekiyor; buna karşılık gençlerin mesleğe ilgisi giderek azalıyor.

Bu hikâye yalnız bir ustanın biyografisi değil, Balıkesir’in çarşı kültüründe yavaş yavaş kaybolan bir mesleğin hafıza kaydı niteliğinde.','Kültür / Zanaat','Buse Tuncay','/assets/haber-kapak/balikesir-in-son-kalaycisi-ilyas-baykal.webp','','published','2024-08-07T09:00:00+03:00','https://gazetemerhaba.com/balikesirin-son-kalaycisi-ilyas-baykal','07 Ağustos 2024','BTmedya için yeniden yazılmış arşiv sürümü. Orijinal yayın bilgileri korunmuştur.','2024-08-07T09:00:00+03:00')
