INSERT INTO news (slug,title,excerpt,body,category,author,cover_url,video_url,status,published_at,source_url,original_date,archive_note,updated_at)
VALUES ('balikesir-esnafi-eleman-bulmakta-zorlaniyor','Balıkesir Esnafı Eleman Bulmakta Zorlanıyor','Balıkesir’de küçük işletmeler 2024 yazında en çok çalışan bulma ve çalışanı işte tutma sorunundan söz ediyordu. 1 Ağustos 2024 tarihli saha haberinde çiğköfteci, kebapçı, kafe, manav, pastane ve market işletmecileriyle görüşülerek iş gücü sıkıntısı farklı yönleriyle ele alındı.','Balıkesir’de küçük işletmeler 2024 yazında en çok çalışan bulma ve çalışanı işte tutma sorunundan söz ediyordu. 1 Ağustos 2024 tarihli saha haberinde çiğköfteci, kebapçı, kafe, manav, pastane ve market işletmecileriyle görüşülerek iş gücü sıkıntısı farklı yönleriyle ele alındı.

Esnafın ortak şikâyeti, uzun çalışma saatlerine karşı çalışanların daha yüksek ücret ve daha esnek koşullar talep etmesi; işe başlayan bazı kişilerin kısa sürede ayrılmasıydı. Bazı işletmeler günlük ödeme talebiyle karşılaştığını, bazıları ise aile bireyleriyle çalışmak zorunda kaldığını anlattı.

Kafe işletmecileri yemek desteği ve sözleşmeli çalışma gibi yöntemleri denerken, bazı esnaf kalıcı çalışan bulabilmek için asgari ücretin üzerinde ödeme yapmayı düşündüğünü söyledi. Buna karşılık çalışan tarafının uzun saatler ve düşük ücret nedeniyle işi sürdürememesi de tablonun diğer yüzüydü.

Haber, sorunu tek taraflı ''eleman yok'' cümlesine indirgemeden çalışma koşulları, ücret ve güven ilişkisi üzerinden yerel iş piyasasının gerilimini gösteriyor.','Ekonomi / Esnaf','Buse Tuncay','/assets/haber-kapak/balikesir-esnafi-eleman-bulmakta-zorlaniyor.webp','','published','2024-08-01T09:00:00+03:00','https://gazetemerhaba.com/balikesir-esnafi-eleman-bulmakta-zorlaniyor','01 Ağustos 2024','BTmedya için yeniden yazılmış arşiv sürümü. Orijinal yayın bilgileri korunmuştur.','2024-08-01T09:00:00+03:00')
