INSERT INTO news (slug,title,excerpt,body,category,author,cover_url,video_url,status,published_at,source_url,original_date,archive_note,updated_at)
VALUES ('balikesir-in-gelin-ayakkabilari-ve-kina-terlikleri-modasi','Balıkesir''in Gelin Ayakkabıları ve Kına Terlikleri Modası','2024 düğün sezonunda Balıkesir’de gelin ayakkabıları ve kına terliklerinde taşlı, tüylü ve incili tasarımlar öne çıktı. 17 Temmuz 2024 tarihli haberde 23 yıllık sektör deneyimi bulunan Özer Özmelek, sezonun tercihlerini ve fiyatlarını anlattı.','2024 düğün sezonunda Balıkesir’de gelin ayakkabıları ve kına terliklerinde taşlı, tüylü ve incili tasarımlar öne çıktı. 17 Temmuz 2024 tarihli haberde 23 yıllık sektör deneyimi bulunan Özer Özmelek, sezonun tercihlerini ve fiyatlarını anlattı.

Kına terlikleri o dönemde yaklaşık 500-800 TL aralığında satılıyor, kullanılan malzeme ve işçiliğe göre bazı modeller 1000 TL’ye kadar çıkabiliyordu. Tüylü ve taşlı modeller kına gecelerinde en çok ilgi gören seçenekler arasındaydı.

Gelin ayakkabılarında ise fiyatlar modele, taş işlemelerine, platforma ve topuk yapısına göre 700 TL’den 1500 TL’ye kadar değişiyordu. Ortalama modeller 1000-1200 TL bandındaydı. İnci detaylı tasarımlar ve yaklaşık 10 santimetrelik orta topuklar, şıklık ile rahatlık arasında denge arayan gelinlerin tercihleri arasındaydı.

Fiyatlar 2024 sezonuna aittir. Arşiv haberi, Balıkesir’de düğün modasının ayrıntılarını küçük ama renkli bir perakende penceresinden gösteriyor.','Moda / Düğün','Buse Tuncay','/assets/haber-kapak/balikesir-in-gelin-ayakkabilari-ve-kina-terlikleri-modasi.webp','','published','2024-07-17T09:00:00+03:00','https://gazetemerhaba.com/gelin-ayakkabilari-ve-kina-terlikleri-modasi','17 Temmuz 2024','BTmedya için yeniden yazılmış arşiv sürümü. Orijinal yayın bilgileri korunmuştur.','2024-07-17T09:00:00+03:00')
