INSERT INTO news (slug,title,excerpt,body,category,author,cover_url,video_url,status,published_at,source_url,original_date,archive_note,updated_at)
VALUES ('balikesir-muay-thai-de-dunya-arenasinda','Balıkesir Muay Thai''de Dünya Arenasında','Balıkesirli Muay Thai sporcusu Hasan Buğra Kösüş, 16 Temmuz 2024 tarihli haberde sporun teknik yapısını, kültürel geçmişini ve profesyonel antrenman düzenini anlattı.','Balıkesirli Muay Thai sporcusu Hasan Buğra Kösüş, 16 Temmuz 2024 tarihli haberde sporun teknik yapısını, kültürel geçmişini ve profesyonel antrenman düzenini anlattı.

''Sekiz uzvun sanatı'' olarak bilinen Muay Thai; yumruk, tekme, diz ve dirsek tekniklerini birlikte kullanmasıyla diğer dövüş sporlarından ayrılıyor. Kösüş, özellikle baskılı dövüş stili ile diz ve dirsek tekniklerinin müsabaka stratejisinde önemli yer tuttuğunu belirtti.

Profesyonel sporcuların antrenman yükü oldukça yüksek. Haberde, hobi amaçlı çalışanların haftada birkaç gün antrenman yaparken profesyonellerin günlük koşu ve yaklaşık 1,5 saatlik teknik çalışmayı programlarına eklediği aktarılmıştı.

Haber, Muay Thai’yi yalnız sert bir dövüş sporu olarak değil disiplin, kondisyon ve kültür boyutlarıyla ele alıyor; Balıkesir’den uluslararası arenaya çıkan sporcuların hikâyesini de görünür kılıyor.','Spor','Buse Tuncay','/assets/haber-kapak/balikesir-muay-thai-de-dunya-arenasinda.webp','','published','2024-07-16T09:00:00+03:00','https://gazetemerhaba.com/balikesir-muay-thaide-dunya-arenasinda','16 Temmuz 2024','BTmedya için yeniden yazılmış arşiv sürümü. Orijinal yayın bilgileri korunmuştur.','2024-07-16T09:00:00+03:00')
