INSERT INTO news (slug,title,excerpt,body,category,author,cover_url,video_url,status,published_at,source_url,original_date,archive_note,updated_at)
VALUES ('kadin-firincidan-30-yillik-basari-oykusu','Kadın Fırıncıdan 30 Yıllık Başarı Öyküsü','Balıkesir Plevne Mahallesi’nde yaşayan Funda Şen, 15 yaşında başladığı fırıncılık mesleğinde 30 yılı geride bıraktığında 45 yaşındaydı. 12 Temmuz 2024 tarihli haber, Şen’in taş fırın başında geçen çalışma hayatını ve ailesiyle kurduğu üretim düzenini anlatıyordu.','Balıkesir Plevne Mahallesi’nde yaşayan Funda Şen, 15 yaşında başladığı fırıncılık mesleğinde 30 yılı geride bıraktığında 45 yaşındaydı. 12 Temmuz 2024 tarihli haber, Şen’in taş fırın başında geçen çalışma hayatını ve ailesiyle kurduğu üretim düzenini anlatıyordu.

Şen, babasından devraldığı yaklaşık 50 yıllık taş fırında eşi ve çocuklarıyla birlikte çalışıyor. Hamurun hazırlanmasından odun ateşinin kontrolüne kadar işin her aşamasında yer alması, onu Balıkesir’de nadir görülen kadın fırın ustalarından biri haline getirdi.

Fırında haşhaşlı ve cevizli çörek, kurabiye, poğaça, açma ve farklı tatlılar hazırlanıyor. Özellikle haşhaşlı çöreğin Balıkesirlilerden yoğun ilgi gördüğünü söyleyen Şen, geleneksel taş fırın yöntemini korumayı önemsiyor.

Yıllarca çalışarak çocuklarının eğitimine katkı sağlayan Şen’in hikâyesi, aile emeği, kadın girişimciliği ve geleneksel üretimin aynı fırında buluştuğu güçlü bir yerel portre.','İnsan Hikâyesi','Buse Tuncay','/assets/haber-kapak/kadin-firincidan-30-yillik-basari-oykusu.webp','','published','2024-07-12T09:00:00+03:00','https://gazetemerhaba.com/kadin-firincidan-30-yillik-basari-oykusu','12 Temmuz 2024','BTmedya için yeniden yazılmış arşiv sürümü. Orijinal yayın bilgileri korunmuştur.','2024-07-12T09:00:00+03:00')
