INSERT INTO news (slug,title,excerpt,body,category,author,cover_url,video_url,status,published_at,source_url,original_date,archive_note,updated_at)
VALUES ('sogan-tarlada-5-pazarda-15tl','Soğan Tarlada 5 Pazarda 15TL','Soğan ve patates fiyatlarındaki üretici-tüketici makası 28 Mayıs 2024 tarihli haberde pazar esnafı Hakan Seren’in değerlendirmeleriyle gündeme taşındı. Seren, soğanın sezon başında daha yüksek fiyatla satılırken tarlada 5 TL seviyesine kadar gerilediğini anlattı.','Soğan ve patates fiyatlarındaki üretici-tüketici makası 28 Mayıs 2024 tarihli haberde pazar esnafı Hakan Seren’in değerlendirmeleriyle gündeme taşındı. Seren, soğanın sezon başında daha yüksek fiyatla satılırken tarlada 5 TL seviyesine kadar gerilediğini anlattı.

Esnafın dikkat çektiği temel konu, tarladaki 5-6 TL’lik fiyat ile pazar ve markette 15-20 TL’ye ulaşan satış fiyatı arasındaki farktı. Seren, perakendecilerin alış ve satış fiyatlarının daha şeffaf olması gerektiğini savundu.

Patateste ise maliyetin yaklaşık 10 TL civarında olduğunu, bu nedenle fiyatın bunun altına düşmesinin üreticiyi zorlayacağını belirtti. 15-20 TL bandının sürdürülebilir olabileceğini, Bolu patatesinin ağustos sonundaki hasadıyla piyasanın yeniden şekillenebileceğini ifade etti.

12-13 yaşından beri patates, soğan ve sarımsak ticaretinin içinde olan Seren’in gözlemleri, 2024 ilkbaharında tarımsal fiyatların üreticiden tüketiciye uzanan zincirde nasıl değiştiğini gösteriyor.','Tarım / Ekonomi','Buse Tuncay','/assets/haber-kapak/sogan-tarlada-5-pazarda-15tl.webp','','published','2024-05-28T09:00:00+03:00','https://gazetemerhaba.com/sogan-tarlada-5-pazarda-15tl','28 Mayıs 2024','BTmedya için yeniden yazılmış arşiv sürümü. Orijinal yayın bilgileri korunmuştur.','2024-05-28T09:00:00+03:00')
