INSERT INTO news (slug,title,excerpt,body,category,author,cover_url,video_url,status,published_at,source_url,original_date,archive_note,updated_at)
VALUES ('balikesir-pazarinda-canli-helva-sovu','Balıkesir Pazarında Canlı Helva Şovu','Balıkesir Gümüşçeşme Mahallesi’nde kurulan Pazar Pazarı, 2 Mayıs 2024 tarihli görüntülü haberde geleneksel helva üretiminin sahneye dönüştüğü renkli bir tezgâha ev sahipliği yaptı. Helva ustası Mustafa Aybacı, ürünlerini müşterilerin gözü önünde hazırlayarak hem üretimi hem satışı aynı yerde buluşturuyordu.','Balıkesir Gümüşçeşme Mahallesi’nde kurulan Pazar Pazarı, 2 Mayıs 2024 tarihli görüntülü haberde geleneksel helva üretiminin sahneye dönüştüğü renkli bir tezgâha ev sahipliği yaptı. Helva ustası Mustafa Aybacı, ürünlerini müşterilerin gözü önünde hazırlayarak hem üretimi hem satışı aynı yerde buluşturuyordu.

Aybacı, aileden gelen helvacılık geleneğini sürdürdüğünü ve tahin helvası ile yaz helvası gibi çeşitleri kendi imalathanelerinde yaptıklarını anlattı. Üretimde şeker ve tahin temel malzemeler arasında yer alıyor; kıvamın tutturulması için karışımın tahta kaşık ve kürekle uzun süre işlenmesi gerekiyor.

O tarihte sekiz çeşit helva bulunduğu, sade ve kakaolu tahin helvasının yaklaşık 180 TL, yaz helvasının 120 TL, cevizli yaz helvasının 160 TL civarında satıldığı aktarılmıştı. Fiyatlar Mayıs 2024 arşivine aittir.

Bu haberin en güçlü yanı görüntüsü: geleneksel üretimin pazarda canlı biçimde yapılması. Video bağlantısı BTmedya arşiv paketine ayrıca eklendi.','Gastronomi / Video','Buse Tuncay','/assets/haber-kapak/balikesir-pazarinda-canli-helva-sovu.webp','https://www.youtube.com/watch?v=iaRHeI78TAk','published','2024-05-02T09:00:00+03:00','https://gazetemerhaba.com/balikesir-pazarinda-canli-helva-sovu','02 Mayıs 2024','BTmedya için yeniden yazılmış arşiv sürümü. Orijinal yayın bilgileri korunmuştur.','2024-05-02T09:00:00+03:00')
