INSERT INTO news (slug,title,excerpt,body,category,author,cover_url,video_url,status,published_at,source_url,original_date,archive_note,updated_at)
VALUES ('beydonoglu-yaprak-satarken-festival-yonetiyor','Beydonoğlu Yaprak Satarken Festival Yönetiyor','Yaş sebze ve meyve ticareti ile hayvancılıkla uğraşan İsmail Beydonoğlu, 2 Mayıs 2024 tarihli görüntülü haberde hem taze yaprak ticaretini hem de bölgesel festival çalışmalarını anlattı.','Yaş sebze ve meyve ticareti ile hayvancılıkla uğraşan İsmail Beydonoğlu, 2 Mayıs 2024 tarihli görüntülü haberde hem taze yaprak ticaretini hem de bölgesel festival çalışmalarını anlattı.

Manisa Alaşehir çevresinden temin edilen taze asma yapraklarını farklı illerde müşterilere ulaştıran Beydonoğlu, üreticiden mümkün olduğunca yüksek fiyatla alıp tüketiciye uygun fiyatla satmaya çalıştığını söyledi. O tarihte yaprağın kilosu yaklaşık 75 TL, üç kilosu 200 TL olarak belirtilmişti.

Ticaretin yanında etkinlik organizasyonlarına da ağırlık veren Beydonoğlu, Turgutlu’da kiraz festivali hazırlıkları yaptığını, Balıkesir Pamukçu’da ise sarımsak festivali düzenleme fikrini gündeme getirdiğini anlattı.

Haber, bir esnafın günlük ticaretinin yerel ürünleri tanıtan festivaller ve sosyal girişimlerle nasıl birleşebildiğini gösteriyor. Görüntülü haberin YouTube bağlantısı paket içinde korunmuştur.','Tarım / Etkinlik / Video','Buse Tuncay','/assets/haber-kapak/beydonoglu-yaprak-satarken-festival-yonetiyor.webp','https://www.youtube.com/watch?v=1c70ybbtjYk','published','2024-05-02T09:00:00+03:00','https://gazetemerhaba.com/beydonoglu-yaprak-satarken-festival-yonetiyor','02 Mayıs 2024','BTmedya için yeniden yazılmış arşiv sürümü. Orijinal yayın bilgileri korunmuştur.','2024-05-02T09:00:00+03:00')
